from itertools import combinations
def block_list(g):
    return blocks(g)
def vals(b, fn): return set(fn(r,c) for r,c in b)
def solve(g):
    bs=blocks(g); n=len(bs)
    adj=[set() for _ in range(n)]
    fns=[lambda r,c:r, lambda r,c:c, lambda r,c:r-c, lambda r,c:r+c]
    for i,j in combinations(range(n),2):
        if any(vals(bs[i],f)&vals(bs[j],f) for f in fns):
            adj[i].add(j); adj[j].add(i)
    paths=[]
    def dfs(path,used):
        if len(path)==n: paths.append(path[:]); return
        for nxt in adj[path[-1]]:
            if nxt not in used:
                dfs(path+[nxt], used|{nxt})
    for s in range(n): dfs([s],{s})
    colorings=set()
    for p in paths:
        for start in (8,2):
            col={}
            ok=True
            for idx,b in enumerate(p):
                c=start if idx%2==0 else (2 if start==8 else 8)
                if b in col and col[b]!=c: ok=False;break
                col[b]=c
            if ok: colorings.add(tuple(sorted((i,col[i]) for i in range(n))))
    return bs, paths, colorings
