import os, re
d=os.environ['RLM_SESSION_DIR']
path=d+'/../../sessions/'+os.path.basename(d)+'.jsonl'
text=open(path).read().replace('\\n','\n')
pat=re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n')
matches=[(m.start(), m.group(1), int(m.group(2)), int(m.group(3))) for m in pat.finditer(text)]
def parse(pos,h,w):
    rows=[]
    for line in text[pos:].split('\n')[1:]:
        if not re.fullmatch(r'[\d ]*', line) or line.strip()=='' and rows: break
        vals=[int(x) for x in line.split()]
        if len(vals)==w: rows.append(vals)
        else: break
        if len(rows)==h: break
    return rows
