def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    seen=[[False]*w for _ in range(h)]
    tls=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0 and not seen[i][j]:
                col=grid[i][j]
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<h and 0<=cc<w and not seen[rr][cc] and grid[rr][cc]==col:
                            seen[rr][cc]=True; stack.append((rr,cc))
                tls.append((min(c for _,c in cells), min(r for r,_ in cells), col))
    out=[row[:] for row in grid]
    tls.sort(reverse=True)  # rightmost first
    for idx,(c0,r0,col) in enumerate(tls):
        new=8 if idx%2==0 else 2
        for r in range(r0,r0+2):
            for c in range(c0,c0+2):
                if 0<=r<h and 0<=c<w and out[r][c]==col:
                    out[r][c]=new
    return out

